{

"kind": "propose",
"summary": "The API container in the search Deployment is throttled at its CPU limit, causing readiness probe failures. Raising the CPU limit from 500m to 750m should alleviate throttling.",
"hypotheses": [
  {
    "root_cause_class": "cpu_limit_too_low",
    "summary": "Container 'api' is throttled at 0.5 CPU limit (usage 0.495), with 64% throttling ratio, causing readiness failures.",
    "supporting": ["ev-container_cpu"],
    "contradicting": [],
    "missing": ["container_logs_tail"],
    "status": "supported"
  },
  {
    "root_cause_class": "new_version_uses_more_cpu",
    "summary": "Earlier revision (1) has no pods left to assess, but rollout_recent is false, so this is unlikely.",
    "supporting": ["ev-rollout_history"],
    "contradicting": ["rollout_recent"],
    "missing": [],
    "status": "refuted"
  }
],
"proposal": {
  "capability": "deployment.set-resources",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "search",
    "uid": "uid-deployment-search"
  },
  "params": {
    "containers": {
      "api": {
        "limits": {
          "cpu": "750m"
        }
      }
    }
  },
  "expected_effect": "Raises CPU limit to 750m, clearing throttling and allowing the container to meet its CPU demand without hitting the limit.",
  "rationale": "Throttling_data_available is true, cpu_throttled_at_limit and cpu_usage_near_limit are true, and readiness probes are failing. Raising the limit to 1.5x current (500m → 750m) addresses sustained throttling without affecting memory or other containers.",
  "cited_evidence_ids": ["ev-container_cpu", "ev-rollout_history"],
  "cited_predicates": ["throttling_data_available", "cpu_throttled_at_limit", "cpu_usage_near_limit", "rollout_recent"]
}
}
